462	CREATE OR REPLACE FUNCTION public.upsert_concepts(v_space_id bigint, data jsonb, v_creator_id BIGINT DEFAULT null, content_as_document boolean DEFAULT true)
463	RETURNS SETOF BIGINT
464	SET search_path = ''
465	LANGUAGE plpgsql
466	AS $$
467	DECLARE
468	  v_platform public."Platform";
469	  local_concept public.concept_local_input;
470	  db_concept public."Concept"%ROWTYPE;
471	  concept_row JSONB;
472	  concept_id BIGINT;
473	  content_inline public.content_local_input;
474	  contents_inline public.content_local_input[];
475	  contents_upsert_result BIGINT[];
476	BEGIN
477	  SELECT platform INTO STRICT v_platform FROM public."Space" WHERE id=v_space_id;
478	  FOR concept_row IN SELECT * FROM jsonb_array_elements(data)
479	  LOOP
480	    -- first set defaults
481	    local_concept := jsonb_populate_record(NULL::public.concept_local_input, '{"epistemic_status": "unknown", "literal_content":{},"reference_content":{},"is_schema":false}');
482	    -- then input values
483	    local_concept := jsonb_populate_record(local_concept, concept_row);
484	    local_concept.space_id := v_space_id;
485	    BEGIN
486	        db_concept := public._local_concept_to_db_concept(local_concept);
487	        IF NOT account_local_id(author_inline(local_concept)) IS NULL THEN
488	          SELECT public.create_account_in_space(
489	            v_space_id,
490	            account_local_id(author_inline(local_concept)),
491	            name(author_inline(local_concept))
492	          ) INTO STRICT db_concept.author_id;
493	        END IF;
494	        -- cannot use db_concept.* because of refs.
495	        INSERT INTO public."Concept" (
496	        epistemic_status, name, description, author_id, created, last_modified, space_id, schema_id, literal_content, is_schema, source_local_id, reference_content
497	        ) VALUES (
498	        db_concept.epistemic_status, db_concept.name, db_concept.description, db_concept.author_id, db_concept.created, db_concept.last_modified, db_concept.space_id, db_concept.schema_id, db_concept.literal_content, db_concept.is_schema, db_concept.source_local_id, db_concept.reference_content
499	        )
500	        ON CONFLICT (space_id, source_local_id) DO UPDATE SET
501	            epistemic_status = db_concept.epistemic_status,
502	            name = db_concept.name,
503	            description = db_concept.description,
504	            author_id = db_concept.author_id,
505	            created = db_concept.created,
506	            last_modified = db_concept.last_modified,
507	            schema_id = db_concept.schema_id,
508	            literal_content = db_concept.literal_content,
509	            is_schema = db_concept.is_schema,
510	            reference_content = db_concept.reference_content
511	        -- If the syntax allowed two conflict clauses, I would add
512	        -- ON CONFLICT (space_id, name) DO NOTHING
513	        -- but since not, I have to handle it as an exception.
514	        RETURNING id INTO concept_id;
515	        IF NOT contents_inline(local_concept) IS NULL THEN
516	            contents_inline := '{}'::public.content_local_input[];
517	            IF NOT document_inline(local_concept) IS NULL THEN
518	                IF author_local_id(document_inline(local_concept)) IS NULL AND author_local_id(local_concept) IS NOT NULL THEN
519	                    local_concept.document_inline.author_local_id := author_local_id(local_concept);
520	                END IF;
521	                IF author_inline(document_inline(local_concept)) IS NULL AND NOT author_inline(local_concept) IS NULL THEN
522	                    local_concept.document_inline.author_inline := author_inline(local_concept);
523	                END IF;
524	                IF created(document_inline(local_concept)) IS NULL  THEN
525	                    local_concept.document_inline.created := created(local_concept);
526	                END IF;
527	                IF last_modified(document_inline(local_concept)) IS NULL THEN
528	                    local_concept.document_inline.last_modified := last_modified(local_concept);
529	                END IF;
530	                IF content_type(document_inline(local_concept)) IS NULL THEN
531	                  local_concept.document_inline.content_type := CASE
532	                    WHEN v_platform='Roam' THEN 'text/roam+markdown'
533	                    WHEN v_platform='Obsidian' THEN 'text/obsidian+markdown'
534	                    ELSE 'text/plain' END;
535	                END IF;
536	            END IF;
537	            FOREACH content_inline IN ARRAY contents_inline(local_concept)
538	            LOOP
539	                IF author_id(content_inline) IS NULL AND author_id(local_concept) IS NOT NULL THEN
540	                    content_inline.author_id := local_concept.author_id;
541	                ELSIF author_local_id(content_inline) IS NULL AND author_local_id(local_concept) IS NOT NULL THEN
542	                    content_inline.author_local_id := local_concept.author_local_id;
543	                ELSIF author_inline(content_inline) IS NULL AND NOT author_inline(local_concept) IS NULL THEN
544	                    content_inline.author_inline := local_concept.author_inline;
545	                END IF;
546	                IF content_type(content_inline) IS NULL THEN
547	                    content_inline.content_type := 'text/plain';
548	                END IF;
549	                IF creator_id(content_inline) IS NULL THEN
550	                    IF creator_local_id(content_inline) IS NULL AND creator_local_id(local_concept) IS NOT NULL THEN
551	                        content_inline.creator_local_id := local_concept.creator_local_id;
552	                    ELSIF creator_inline(content_inline) IS NULL AND NOT creator_inline(local_concept) IS NULL THEN
553	                        content_inline.creator_inline := local_concept.creator_inline;
554	                    END IF;
555	                END IF;
556	                IF document_id(content_inline) IS NULL THEN
557	                    IF document_local_id(content_inline) IS NULL AND document_local_id(local_concept) IS NOT NULL THEN
558	                        content_inline.document_local_id := local_concept.document_local_id;
559	                    ELSIF document_inline(content_inline) IS NULL AND NOT document_inline(local_concept) IS NULL THEN
560	                        content_inline.document_inline := local_concept.document_inline;
561	                    END IF;
562	                    IF content_type(document_inline(content_inline)) IS NULL THEN
563	                      content_inline.document_inline.content_type := CASE
564	                        WHEN v_platform='Roam' THEN 'text/roam+markdown'
565	                        WHEN v_platform='Obsidian' THEN 'text/obsidian+markdown'
566	                        ELSE 'text/plain' END;
567	                    END IF;
568	                END IF;
569	                IF source_local_id(content_inline) IS NULL AND source_local_id(local_concept) IS NOT NULL THEN
570	                    content_inline.source_local_id := local_concept.source_local_id;
571	                END IF;
572	                IF space_url(content_inline) IS NULL AND space_url(local_concept) IS NOT NULL THEN
573	                    content_inline.space_url := local_concept.space_url;
574	                END IF;
575	                IF created(content_inline) IS NULL AND created(local_concept) IS NOT NULL THEN
576	                    content_inline.created := local_concept.created;
577	                END IF;
578	                IF last_modified(content_inline) IS NULL AND last_modified(local_concept) IS NOT NULL THEN
579	                    content_inline.last_modified := local_concept.last_modified;
580	                END IF;
581	                SELECT array_append(contents_inline, content_inline) INTO contents_inline;
582	            END LOOP;
583	            SELECT array_agg(ct) FROM public.upsert_content(v_space_id, to_jsonb(contents_inline), v_creator_id, content_as_document) AS ct INTO contents_upsert_result;
584	            -- Q: Should we not fail the concept upsert if that content upsert failed? Currently the case.
585	        END IF;
586	        RETURN NEXT concept_id;
587	    EXCEPTION
588	        WHEN unique_violation THEN
589	            -- a distinct unique constraint failed
590	            RAISE WARNING 'Concept with space_id: % and name % already exists', v_space_id, local_concept.name;
591	            RETURN NEXT -1; -- Return a special value to indicate conflict
592	        WHEN OTHERS THEN
593	            -- Null value; probably due to a missing concept.
594	            RAISE WARNING 'Error in concept upsert: (%) %', SQLSTATE, SQLERRM;
595	            RETURN NEXT -2; -- Return a special value to indicate error
596	    END;
597	  END LOOP;
598	  RAISE DEBUG 'Completed upsert_concepts successfully';
599	END;
600	$$;
