265	const chunk = <T>(array: T[], size: number): T[][] => {
266	  const chunks: T[][] = [];
267	  for (let i = 0; i < array.length; i += size) {
268	    chunks.push(array.slice(i, i + size));
269	  }
270	  return chunks;
271	};
