273	const summarizeFailedConceptUpsertIds = (failedIds: number[]): string => {
274	  const counts = failedIds.reduce<Record<string, number>>((acc, id) => {
275	    acc[id] = (acc[id] ?? 0) + 1;
276	    return acc;
277	  }, {});
278	
279	  return Object.entries(counts)
280	    .map(([id, count]) => `${id}: ${count}`)
281	    .join(", ");
282	};
