44	      [?page_id :block/uid ?page_uid]
45	  ]`,
46	    node_uid,
47	  );
48	  if (result.length !== 1 || result[0].length !== 4)
49	    throw new Error("Invalid result from Roam query");
50	
51	  const [author_uid, page_uid, created_t, last_modified_t] = result[0] as [
52	    string,
53	    string,
54	    number,
55	    number,
56	  ];
57	  const created = new Date(created_t).toISOString();
58	  const last_modified = new Date(last_modified_t).toISOString();
59	  return {
60	    author_local_id: author_uid,
61	    created,
62	    last_modified,
63	    page_uid,
64	  };
65	  /* eslint-enable @typescript-eslint/naming-convention */
66	};
