154	export const discourseRelationDataToLocalConcept = (
155	  context: SupabaseContext,
156	  relationUid: string,
157	): LocalConceptDataInput => {
158	  // assuming reified
159	  const relationProps = getBlockProps(relationUid);
160	  const relationSchemaData = relationProps[DISCOURSE_GRAPH_PROP_NAME] as Record<
161	    string,
162	    string
163	  >;
164	  if (!relationSchemaData) {
165	    throw new Error(`Missing relation data for ${relationUid}`);
166	  }
167	  const relationSchemaUid = relationSchemaData.hasSchema;
168	  if (!relationSchemaUid) {
169	    throw new Error(`Missing relation schema uid for ${relationUid}`);
170	  }
171	  const roamRelation = getDiscourseRelations().find(
172	    (r) => r.id === relationSchemaUid,
173	  );
174	  if (roamRelation === undefined) {
175	    throw new Error(`Invalid roam relation id ${relationSchemaUid}`);
176	  }
177	  const relation = discourseRelationSchemaToLocalConcept(context, roamRelation);
178	  const litContent = (
179	    relation.literal_content ? relation.literal_content : {}
180	  ) as { [key: string]: Json };
181	  const roles = (litContent["roles"] as string[] | undefined) || STANDARD_ROLES;
182	  const casting = Object.fromEntries(
183	    roles
184	      .map((role) => [role, relationSchemaData[role + "Uid"]])
185	      .filter(([, uid]) => uid !== undefined),
186	  ) as { [role: string]: string };
187	  if (Object.keys(casting).length === 0) {
188	    throw new Error(
189	      `No valid node UIDs supplied for roles ${roles.join(", ")}`,
190	    );
191	  }
192	  // TODO: Also get the nodes from the representation, using QueryBuilder. That will likely give me the relation object
193	  const nodeData = Object.values(casting).map((v) => getNodeExtraData(v));
194	  // roundabout way to do a max from stringified dates
195	  const last_modified = new Date(
196	    Math.max(...nodeData.map((nd) => new Date(nd.last_modified).getTime())),
197	  ).toISOString();
198	  // creation is actually creation of the relation node, not the rest of the cast, but this will do as a first approximation.
199	  // Still using max, since the relation cannot be created before its cast
200	  const created = new Date(
201	    Math.max(...nodeData.map((nd) => new Date(nd.created).getTime())),
202	  ).toISOString();
203	  const author_local_id: string = nodeData[0].author_local_id; // take any one; again until I get the relation object
204	  return {
205	    space_id: context.spaceId,
206	    source_local_id: relationUid,
207	    author_local_id,
208	    created,
209	    last_modified,
210	    name: relationUid,
211	    is_schema: false,
212	    schema_represented_by_local_id: relationSchemaUid,
213	    local_reference_content: casting,
214	  };
215	  /* eslint-enable @typescript-eslint/naming-convention */
216	};
