218	export const relatedConcepts = (concept: LocalConceptDataInput): string[] => {
219	  const relations = Object.values(
220	    concept.local_reference_content || {},
221	  ).flat() as string[];
222	  if (concept.schema_represented_by_local_id) {
223	    relations.push(concept.schema_represented_by_local_id);
224	  }
225	  // remove duplicates
226	  return [...new Set(relations)];
227	};
