229	const orderConceptsRec = ({
230	  ordered,
231	  concept,
232	  remainder,
233	  processed,
234	}: {
235	  ordered: LocalConceptDataInput[];
236	  concept: LocalConceptDataInput;
237	  remainder: { [key: string]: LocalConceptDataInput };
238	  processed: Set<string>;
239	}): Set<string> => {
240	  // Add to processed at the start to prevent cycles
241	  processed.add(concept.source_local_id!);
242	
243	  const relatedConceptIds = relatedConcepts(concept);
244	  let missing: Set<string> = new Set();
245	  while (relatedConceptIds.length > 0) {
246	    const relatedConceptId = relatedConceptIds.shift()!;
247	    if (processed.has(relatedConceptId)) continue;
248	    const relatedConcept = remainder[relatedConceptId];
249	    if (relatedConcept === undefined) {
250	      missing.add(relatedConceptId);
251	    } else {
252	      missing = new Set([
253	        ...missing,
254	        ...orderConceptsRec({
255	          ordered,
256	          concept: relatedConcept,
257	          remainder,
258	          processed,
259	        }),
260	      ]);
261	      delete remainder[relatedConceptId];
262	    }
263	  }
264	  ordered.push(concept);
265	  delete remainder[concept.source_local_id!];
266	  return missing;
267	};
