269	/*
270	If writing a concept upsert method, you want to insure that
271	a node's dependencies are defined before the node itself is upserted.
272	The dependencies are as defined in relatedConcepts.
273	If you upsert in the following order: [node schemas, relation schemas, nodes, relations]
274	then the depencies will be implicitly respected.
275	(It will be tricker when we have recursive relations.)
276	If you are starting from a random stream of nodes, you would want to order them with this function.
277	It assumes all input has defined source_local_id,
278	and that nodes that are not in the upsert set are already in the database.
279	the Id of those nodes is returned and can be used to check that assumption.
280	We also assume that there are no dependency cycles.
281	 */
282	export const orderConceptsByDependency = (
283	  concepts: LocalConceptDataInput[],
284	): { ordered: LocalConceptDataInput[]; missing: string[] } => {
285	  if (concepts.length === 0) return { ordered: concepts, missing: [] };
286	  const conceptById = Object.fromEntries(
287	    concepts.map((c) => [c.source_local_id, c]),
288	  ) as { [key: string]: LocalConceptDataInput };
289	  const ordered: LocalConceptDataInput[] = [];
290	  let missing: Set<string> = new Set();
291	  const processed: Set<string> = new Set();
292	  while (Object.keys(conceptById).length > 0) {
293	    const first = Object.values(conceptById)[0];
294	    missing = new Set([
295	      ...missing,
296	      ...orderConceptsRec({
297	        ordered,
298	        concept: first,
299	        remainder: conceptById,
300	        processed,
301	      }),
302	    ]);
303	  }
304	  return { ordered, missing: [...missing] };
305	};
