322	CREATE OR REPLACE FUNCTION public.rid_to_space_id_and_local_id(rid VARCHAR)
323	RETURNS public.accessible_resource STRICT STABLE
324	SET search_path = ''
325	LANGUAGE plpgsql AS $$
326	DECLARE
327	    uri VARCHAR;
328	    source_local_id VARCHAR;
329	    source_id BIGINT;
330	BEGIN
331	source_local_id := split_part(rid, '/', -1);
332	IF length(source_local_id) = length(rid) THEN
333	    RETURN (null, 'Not a Rid')::public.accessible_resource;
334	END IF;
335	uri := substr(rid, 1, length(rid) - length(source_local_id) - 1);
336	IF rid ~ '^orn:\w+\.\w+:.*$' THEN
337	    uri := concat(split_part(split_part(uri, ':', 2), '.', 1), ':', split_part(uri, ':', 3));
338	ELSE
339	    IF rid ~ '^orn:\w+:.*$' THEN
340	        uri := substr(uri, 5);
341	    END IF;
342	END IF;
343	SELECT id INTO source_id FROM public."Space" where url=uri;
344	IF source_id IS NULL THEN
345	    RETURN (null, concat('Cannot find ', uri))::public.accessible_resource;
346	END IF;
347	RETURN (source_id, source_local_id);
348	END;
349	$$;
