351	CREATE OR REPLACE FUNCTION public.rid_or_local_id_to_concept_db_id(rid VARCHAR, default_space_id BIGINT)
352	RETURNS BIGINT STRICT STABLE
353	SET search_path = ''
354	LANGUAGE plpgsql AS $$
355	DECLARE r public.accessible_resource;
356	BEGIN
357	    r := (SELECT public.rid_to_space_id_and_local_id(rid));
358	    IF r.space_id IS NULL THEN
359	        RETURN  (SELECT id FROM public."Concept" WHERE space_id = default_space_id AND source_local_id = rid);
360	    ELSE
361	        RETURN (SELECT id FROM public."Concept" WHERE space_id = r.space_id AND source_local_id = r.source_local_id);
362	    END IF;
363	END;
364	$$;
