396	CREATE OR REPLACE FUNCTION public._local_concept_to_db_concept(data public.concept_local_input)
397	RETURNS public."Concept" STABLE
398	SET search_path = ''
399	LANGUAGE plpgsql
400	AS $$
401	DECLARE
402	  concept public."Concept"%ROWTYPE;
403	  reference_content JSONB := jsonb_build_object();
404	  key varchar;
405	  value JSONB;
406	  ref_single_val BIGINT;
407	  ref_array_val BIGINT[];
408	BEGIN
409	  -- not fan of going through json, but not finding how to populate a record by a different shape record
410	  concept := jsonb_populate_record(NULL::public."Concept", to_jsonb(data));
411	  IF data.author_local_id IS NOT NULL THEN
412	    SELECT id FROM public."PlatformAccount"
413	      WHERE account_local_id = data.author_local_id INTO concept.author_id;
414	  ELSIF account_local_id(author_inline(data)) IS NOT NULL THEN
415	    SELECT id FROM public."PlatformAccount"
416	        WHERE account_local_id = account_local_id(author_inline(data)) INTO concept.author_id;
417	  END IF;
418	  IF data.represented_by_id IS NOT NULL THEN
419	    SELECT space_id, source_local_id FROM public."Content"
420	      WHERE id = data.represented_by_id INTO concept.space_id, concept.source_local_id;
421	  END IF;
422	  IF data.space_url IS NOT NULL THEN
423	    SELECT id FROM public."Space"
424	    WHERE url = data.space_url INTO concept.space_id;
425	  END IF;
426	  IF concept.source_local_id = '' THEN
427	    concept.source_local_id := NULL;
428	  END IF;
429	  IF data.represented_by_local_id = '' THEN
430	    data.represented_by_local_id := NULL;
431	  END IF;
432	  IF data.schema_represented_by_local_id IS NOT NULL THEN
433	    SELECT public.rid_or_local_id_to_concept_db_id(
434	        data.schema_represented_by_local_id, concept.space_id) INTO concept.schema_id;
435	  END IF;
436	  concept.source_local_id = COALESCE(concept.source_local_id, data.represented_by_local_id); -- legacy input field
437	  concept.reference_content := coalesce(data.reference_content, '{}'::jsonb);
438	  IF data.local_reference_content IS NOT NULL THEN
439	    FOR key, value IN SELECT * FROM jsonb_each(data.local_reference_content) LOOP
440	      IF jsonb_typeof(value) = 'array' THEN
441	        WITH el AS (SELECT jsonb_array_elements_text(value) as x),
442	        el2 AS (SELECT public.rid_or_local_id_to_concept_db_id(x, concept.space_id) AS id FROM el)
443	        SELECT array_agg(DISTINCT el2.id) INTO STRICT ref_array_val
444	            FROM el2 WHERE el2.id IS NOT NULL;
445	        reference_content := jsonb_set(reference_content, ARRAY[key], to_jsonb(ref_array_val));
446	      ELSIF jsonb_typeof(value) = 'string' THEN
447	        SELECT public.rid_or_local_id_to_concept_db_id(value #>> '{}', concept.space_id) INTO STRICT ref_single_val;
448	        reference_content := jsonb_set(reference_content, ARRAY[key], to_jsonb(ref_single_val));
449	      ELSE
450	        RAISE EXCEPTION 'Invalid value in local_reference_content % %', value, jsonb_typeof(value);
451	      END IF;
452	    END LOOP;
453	    concept.reference_content := concept.reference_content || reference_content;
454	  END IF;
455	  RETURN concept;
456	END;
457	$$;

1	import {
2	  CONTENT_PLACEHOLDER,
3	  FORMAT_PLACEHOLDER,
4	} from "@repo/database/lib/decorateTitle";
5	import getDiscourseNodes, { type DiscourseNode } from "./getDiscourseNodes";
6	import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";
7	import { getDiscourseNodeFormatExpression } from "@repo/database/lib/getDiscourseNodeFormatExpression";
8	import { readImportedSourceIdentity } from "./importedSourceIdentity";
9	
10	// Temporary hack, until slots are a first-class node type setting: a node type whose
11	// format has a {source} placeholder (Evidence, among the default node types) is taken
12	// to have a sourceDocument slot, filled by the Source node named in a node's title.
13	// Both the sync and the publish path express this, so it lives here rather than in
14	// either of them.
15	
16	export const SOURCE_SLOT = "sourceDocument";
17	export const MISSING_SOURCE_PLACEHOLDER = "@placeholder";
18	const DEFAULT_SOURCE_SCHEMA_ID = "_SRC-node";
19	const SOURCE_PLACEHOLDER = "{source}";
20	
21	type NodeFormat = Pick<DiscourseNode, "format">;
22	
23	export const schemaHasSourceSlot = (schema: NodeFormat): boolean =>
24	  (schema?.format ?? "").toLowerCase().includes(SOURCE_PLACEHOLDER);
25	
26	const sourceNodeType = (allNodes: DiscourseNode[]): DiscourseNode | undefined =>
27	  allNodes.find((node) => node.text.toLowerCase() === "source");
28	
29	// The node type a sourceDocument slot points at.
30	export const sourceSlotSchemaId = (allNodes?: DiscourseNode[]): string =>
31	  sourceNodeType(allNodes ?? getDiscourseNodes())?.type ??
32	  DEFAULT_SOURCE_SCHEMA_ID;
33	
34	// Compiled once per format: these are matched against every node's source.
35	const formatMatchers = new Map<string, RegExp>();
36	const matcherFor = (format: string): RegExp => {
37	  const cached = formatMatchers.get(format);
38	  if (cached) return cached;
39	  const matcher = getDiscourseNodeFormatExpression(format);
40	  formatMatchers.set(format, matcher);
41	  return matcher;
42	};
43	
44	// A slot may only hold a discourse node: the database resolves its value to a concept,
45	// and a page that is not a discourse node has none, which would be stored as a null
46	// reference. Better to leave the slot out than to fill it with that.
47	//
48	// Which node type it is, we do not check, and that leniency is part of the hack: the
49	// Source type is recognised here by being named "source", and a graph coming from
50	// another app may well name it otherwise. Rejecting anything but a local "Source" node
51	// would silently drop those. This goes away with slots as a real node type setting.
52	const isDiscourseNodeTitle = (
53	  title: string,
54	  allNodes: DiscourseNode[],
55	): boolean =>
56	  allNodes
57	    .filter((n) => n.format !== "{content}") // exclude page and block
58	    .some((node) => matcherFor(node.format).test(title));
59	
60	// The two RID shapes the database resolves (see rid_to_space_id_and_local_id). The
61	// shared parser is not used here: its fallback splits any string at its last slash, so
62	// it accepts values the database will fail to resolve.
63	const ORN_RID = /^orn:\w+(\.\w+)?:.+\/[^/]+$/;
64	
65	const isHttpsRid = (value: string): boolean => {
66	  try {
67	    const { protocol, host } = new URL(value);
68	    const lastSlash = value.lastIndexOf("/");
69	    return (
70	      protocol === "https:" &&
71	      host !== "" &&
72	      lastSlash > "https://".length &&
73	      lastSlash < value.length - 1
74	    );
75	  } catch {
76	    return false;
77	  }
78	};
79	
80	const isWellFormedRid = (value: string): boolean =>
81	  ORN_RID.test(value) || isHttpsRid(value);
82	
83	// The page a node's {source} placeholder resolves to, when there is one: its uid, or
84	// the RID it is known by elsewhere when it was imported from another app. The
85	// placeholder is usually filled with a page reference, and a title holding a slash is
86	// a namespaced page rather than a source, so it is left alone.
87	export const sourceIdOfNode = (
88	  title: string,
89	  schema: NodeFormat | undefined,
90	  allNodes?: DiscourseNode[],
91	): string | undefined => {
92	  if (schema === undefined) return undefined;
93	  if (!schemaHasSourceSlot(schema)) return undefined;
94	  const sourceIndex = (schema.format.match(FORMAT_PLACEHOLDER) ?? []).findIndex(
95	    (placeholder) => placeholder.toLowerCase() === SOURCE_PLACEHOLDER,
96	  );
97	  const sourceTitle = matcherFor(schema.format)
98	    .exec(title)
99	    ?.[sourceIndex + 1].trim()
100	    .replace(/^\[\[(.*)\]\]$/s, "$1")
101	    .trim();
102	  // The missing-source placeholder page is never a real Source.
103	  if (
104	    !sourceTitle ||
105	    sourceTitle === MISSING_SOURCE_PLACEHOLDER ||
106	    sourceTitle.includes("/")
107	  )
108	    return undefined;
109	  if (!isDiscourseNodeTitle(sourceTitle, allNodes ?? getDiscourseNodes()))
110	    return undefined;
111	  const sourceUid = getPageUidByPageTitle(sourceTitle);
112	  if (!sourceUid) return undefined;
113	  const sourceRid = readImportedSourceIdentity(sourceUid)?.sourceNodeRid;
114	  return sourceRid !== undefined && isWellFormedRid(sourceRid)
115	    ? sourceRid
116	    : sourceUid;
117	};
118	
119	const FILLABLE_PLACEHOLDERS = new Set([
120	  CONTENT_PLACEHOLDER,
121	  SOURCE_PLACEHOLDER,
122	]);
123	
124	// Inverse of sourceUidOfNode, for the pull side: the local title of a node whose format
125	// names a source, built from its core title and the Source page's title. Null when the
126	// format has a placeholder neither fills, so the caller keeps the incoming title.
127	export const titleWithSource = ({
128	  format,
129	  coreTitle,
130	  sourceTitle,
131	}: {
132	  format: string;
133	  coreTitle: string;
134	  sourceTitle: string;
135	}): string | null => {
136	  const placeholders = (format.match(FORMAT_PLACEHOLDER) ?? []).map(
137	    (placeholder) => placeholder.toLowerCase(),
138	  );
139	  if (
140	    !placeholders.includes(CONTENT_PLACEHOLDER) ||
141	    placeholders.some((placeholder) => !FILLABLE_PLACEHOLDERS.has(placeholder))
142	  )
143	    return null;
144	  return format.replace(FORMAT_PLACEHOLDER, (placeholder) =>
145	    placeholder.toLowerCase() === CONTENT_PLACEHOLDER
146	      ? coreTitle
147	      : `[[${sourceTitle}]]`,
148	  );
