65	export const getAllDiscourseNodesSince = async (
66	  since: number | undefined,
67	  nodeTypes: DiscourseNode[],
68	): Promise<RoamDiscourseNodeData[]> => {
69	  const sinceMs = since ?? DEFAULT_TIME;
70	  if (!nodeTypes.length) {
71	    return [];
72	  }
73	
74	  const typeMatchers = nodeTypes.map((node) => ({
75	    node,
76	    regex: getDiscourseNodeFormatExpression(node.format),
77	  }));
78	  const regexPattern = typeMatchers
79	    .map(({ regex }) => `(?:${regex.source})`)
80	    .join("|")
81	    .replace(/\\/g, "\\\\")
82	    .replace(/"/g, '\\"');
83	
84	  const query = `[
85	    :find ?node-title ?uid ?nodeCreateTime ?nodeEditTime ?author_local_id ?author_name
86	    :keys text source_local_id created last_modified author_local_id author_name
87	    :in $ ?since
88	    :where
89	      [(re-pattern "${regexPattern}") ?title-regex]
90	      [?node :node/title ?node-title]
91	      [(re-find ?title-regex ?node-title)]
92	      [?node :block/uid ?uid]
93	      [?node :create/time ?nodeCreateTime]
94	      [?node :create/user ?user-eid]
95	      [?user-eid :user/uid ?author_local_id]
96	      [(get-else $ ?user-eid :user/display-name "Anonymous User") ?author_name]
97	      [(get-else $ ?node :edit/time ?nodeCreateTime) ?nodeEditTime]
98	      [(> ?nodeEditTime ?since)]
99	  ]`;
100	
101	  const allPages = (await window.roamAlphaAPI.data.backend.q(
102	    query,
103	    sinceMs,
104	  )) as unknown[] as RoamDiscourseNodeData[];
105	
106	  const resultMap = new Map<string, RoamDiscourseNodeData>();
107	  const blockBackedNodeTypes = nodeTypes.filter((node) =>
