131	
132	      blockNodes.forEach((blockNode) => {
133	        if (blockNode.source_local_id) {
134	          resultMap.set(blockNode.source_local_id, {
135	            ...blockNode,
136	            type: node.type,
137	          });
138	        }
139	      });
140	    }),
141	  );
142	
143	  return Array.from(resultMap.values());
