628	CREATE OR REPLACE FUNCTION public.is_last_local_reference(space_id_ BIGINT, source_local_id_ VARCHAR) RETURNS boolean
629	STABLE
630	SET search_path = ''
631	SECURITY DEFINER
632	LANGUAGE sql
633	AS $$
634	    SELECT NOT EXISTS (SELECT id FROM public."Content" WHERE space_id=space_id_ AND source_local_id=source_local_id_ LIMIT 1)
635	       AND NOT EXISTS (SELECT id FROM public."Concept" WHERE space_id=space_id_ AND source_local_id=source_local_id_ LIMIT 1)
636	       AND NOT EXISTS (SELECT id FROM public."Document" WHERE space_id=space_id_ AND source_local_id=source_local_id_ LIMIT 1);
637	$$;
638	
639	CREATE OR REPLACE FUNCTION on_delete_local_reference() RETURNS TRIGGER
640	SET search_path = ''
641	SECURITY DEFINER
642	LANGUAGE plpgsql
643	AS $$
644	BEGIN
645	    IF public.is_last_local_reference(OLD.space_id, OLD.source_local_id) THEN
646	    DELETE FROM public."ResourceAccess" WHERE space_id=OLD.space_id AND source_local_id=OLD.source_local_id;
647	    END IF;
648	    RETURN OLD;
649	END;
650	$$;
651	
652	CREATE TRIGGER on_delete_content_trigger AFTER DELETE ON public."Content" FOR EACH ROW EXECUTE FUNCTION public.on_delete_local_reference();
